package md.utm.messaging.broker;
import md.utm.messaging.contracts.*; import java.io.*; import java.net.*; import java.util.concurrent.*;
public final class BrokerServer implements AutoCloseable { private final BrokerOptions options; private final BrokerEngine engine; private final ConsumerRegistry registry; private volatile boolean running=true; private ServerSocket server; private final ExecutorService clients=Executors.newCachedThreadPool(); public BrokerServer(BrokerOptions o,BrokerEngine e,ConsumerRegistry r){options=o;engine=e;registry=r;}
 public void run()throws IOException{server=new ServerSocket(options.port());System.out.println("Broker listening on port "+options.port());while(running){try{Socket s=server.accept();clients.submit(()->handle(s));}catch(SocketException e){if(running)throw e;}}}
 private void handle(Socket s){boolean owned=false;try{var r=JsonLineProtocol.reader(s.getInputStream());var w=JsonLineProtocol.writer(s.getOutputStream());TransportFrame f=JsonLineProtocol.read(r); if("publish".equals(f.kind())){boolean ok=engine.publish(f.message());JsonLineProtocol.write(w,ok?TransportFrame.accepted(f.message().id()):TransportFrame.error("Invalid message or schemaVersion"));}else if("registerConsumer".equals(f.kind())){var c=new ConsumerConnection(f.consumerId(),f.destination(),s,r,w);registry.register(f.destination(),c);JsonLineProtocol.write(w,TransportFrame.registered(f.consumerId(),f.destination()));owned=true;System.out.println("Consumer registered: "+f.consumerId()+" -> "+f.destination());}else JsonLineProtocol.write(w,TransportFrame.error("Unsupported frame kind"));}catch(Exception e){System.err.println("Client error: "+e.getMessage());}finally{if(!owned)try{s.close();}catch(Exception ignored){}}}
 public void close(){running=false;try{if(server!=null)server.close();}catch(Exception ignored){}clients.shutdownNow();engine.shutdown();}
}
